const verify = (sha: string, cwd: string) => {
  if (!/^[0-9a-f]{40}$/.test(sha)) throw new Error(`not a sha: ${sha}`);
  execFileSync('git', ['rev-parse', '--verify', '--quiet', `${sha}^{commit}`], { cwd });
};

